  // the alert policies tab
  "A policy is a set of limits. It only runs on the ACs you attach it to (open an AC › Alert policies). Every AC also has the default policy.":
    "Polisi ialah set had. Ia hanya berjalan pada AC yang anda lampirkan (buka AC › Polisi amaran). Setiap AC juga mempunyai polisi lalai.",
  "+ Create policy": "+ Cipta polisi",
  "Default · set by HQ": "Lalai · ditetapkan oleh HQ",
  "{on} of {n} rules on": "{on} daripada {n} peraturan hidup",
  "Limits set by HQ · on / off is set by the account owner": "Had ditetapkan oleh HQ · hidup / mati ditetapkan oleh pemilik akaun",
  "Covers ventilation and the usual causes of breakdowns. It is attached to every AC and cannot be detached or edited, but the account owner can switch each rule on or off for your account (all your ACs); members see the rules read-only. Ask HQ if a limit should change.":
    "Meliputi pengudaraan dan punca biasa kerosakan. Ia dilampirkan pada setiap AC dan tidak boleh dilepaskan atau disunting, tetapi pemilik akaun boleh menghidupkan atau mematikan setiap peraturan untuk akaun anda (semua AC anda); ahli melihat peraturan secara baca sahaja. Tanya HQ jika had perlu diubah.",
