  "Air conditioners in this {kind} ({n})": "Penyaman udara dalam {kind} ini ({n})",
  "Each AC has its own control screen; Group control sends one setting to several ACs in a space. Unit membership is managed in HQ’s unit register.": "Setiap AC mempunyai skrin kawalannya sendiri; Kawalan kumpulan menghantar satu tetapan kepada beberapa AC dalam satu ruang. Keahlian unit diuruskan dalam daftar unit HQ.",
  "Each AC has its own control screen. Unit membership is managed in HQ’s unit register.": "Setiap AC mempunyai skrin kawalannya sendiri. Keahlian unit diuruskan dalam daftar unit HQ.",
  "Renamed to “{name}”": "Dinamakan semula kepada “{name}”",
