  "Each AC gets its own command and confirmation (same as single control). Offline ACs are skipped; restrictions such as a minimum temperature still apply per AC. One space only · owner role only.": "Setiap AC menerima arahan dan pengesahannya sendiri (sama seperti kawalan tunggal). AC luar talian dilangkau; sekatan seperti suhu minimum masih terpakai bagi setiap AC. Satu ruang sahaja · peranan pemilik sahaja.",
