  "Granted {when} · used only by {n} location automation · demo location events (no real GPS history).": "Diberikan {when} · digunakan hanya oleh {n} automasi lokasi · peristiwa lokasi demo (tiada sejarah GPS sebenar).",
  "Granted {when} · used only by {n} location automations · demo location events (no real GPS history).": "Diberikan {when} · digunakan hanya oleh {n} automasi lokasi · peristiwa lokasi demo (tiada sejarah GPS sebenar).",
  "Withdrawn {when} · {n} location automation was turned off and will not run. Granting consent again does NOT turn them back on automatically — you re-enable each one. Manual control is unaffected.": "Ditarik balik {when} · {n} automasi lokasi dimatikan dan tidak akan berjalan. Memberikan persetujuan semula TIDAK menghidupkannya semula secara automatik — anda menghidupkan setiap satu semula. Kawalan manual tidak terjejas.",
  "Withdrawn {when} · {n} location automations were turned off and will not run. Granting consent again does NOT turn them back on automatically — you re-enable each one. Manual control is unaffected.": "Ditarik balik {when} · {n} automasi lokasi dimatikan dan tidak akan berjalan. Memberikan persetujuan semula TIDAK menghidupkannya semula secara automatik — anda menghidupkan setiap satu semula. Kawalan manual tidak terjejas.",
  "Location automations need your consent. It is used only for arrival/departure automations — demo location events, no real GPS history.": "Automasi lokasi memerlukan persetujuan anda. Ia digunakan hanya untuk automasi tiba/pergi — peristiwa lokasi demo, tiada sejarah GPS sebenar.",
