  "Open a window or run your ventilation fan, then log it — the record is kept in this room’s ventilation history.": "Buka tingkap atau hidupkan kipas pengudaraan, kemudian rekodkannya — rekod disimpan dalam sejarah pengudaraan bilik ini.",
  "{unit} has no fresh-air function, so nothing is sent to the AC — open a window, then log what you did.": "{unit} tiada fungsi udara segar, jadi tiada apa-apa dihantar ke AC — buka tingkap, kemudian rekodkan apa yang anda lakukan.",
