  "On hold by HQ — scheduling and reports are blocked until HQ resumes the job.": "Ditangguhkan oleh HQ — penjadualan dan laporan disekat sehingga HQ menyambung semula kerja.",
  "The technician": "Juruteknik",
  "Completed {time} — accepted in the quality review. {name}’s assignment ended with it, so the time is free for other visits (IR234).": "Selesai {time} — diterima dalam semakan kualiti. Penugasan {name} tamat bersamanya, jadi masa itu lapang untuk lawatan lain (IR234).",
  "Completed — accepted in the quality review. {name}’s assignment ended with it, so the time is free for other visits (IR234).": "Selesai — diterima dalam semakan kualiti. Penugasan {name} tamat bersamanya, jadi masa itu lapang untuk lawatan lain (IR234).",
  "Cancelled by HQ — no further work.": "Dibatalkan oleh HQ — tiada kerja lanjut.",
  "The delegation period has ended.": "Tempoh delegasi telah tamat.",
  "Delegation ends {time} — {left} to schedule the work.": "Delegasi tamat {time} — {left} lagi untuk menjadualkan kerja.",
  "Delegation ends {time} — {left} left.": "Delegasi tamat {time} — {left} lagi.",
  "This offer expired or was cancelled by HQ — no decision is possible. The page shows the latest state.": "Tawaran ini telah tamat tempoh atau dibatalkan oleh HQ — tiada keputusan boleh dibuat. Halaman ini menunjukkan keadaan terkini.",
  "The delegation terms changed — reload to read the new terms before deciding.": "Syarat delegasi telah berubah — muat semula untuk membaca syarat baharu sebelum membuat keputusan.",
  "Your time change is still waiting for the client — accept after it is answered or withdraw it.": "Perubahan masa anda masih menunggu pelanggan — terima selepas ia dijawab atau tarik baliknya.",
  "That technician lacks a required qualification valid at the proposed time — choose another.": "Juruteknik itu tiada kelayakan yang diperlukan yang sah pada masa yang dicadangkan — pilih yang lain.",
  "That technician cannot be booked for this unit — choose another.": "Juruteknik itu tidak boleh ditempah untuk unit ini — pilih yang lain.",
  "The offer changed elsewhere — the page shows the latest version.": "Tawaran telah berubah di tempat lain — halaman ini menunjukkan versi terkini.",
