  "Times in {zone}.": "Masa dalam {zone}.",
  "The end must be at or after the current end": "Masa tamat mesti pada atau selepas masa tamat semasa",
  "Visit time (agreed with the client)": "Masa lawatan (dipersetujui dengan pelanggan)",
  "Fixed. A different time needs the client’s approval via HQ.": "Tetap. Masa lain memerlukan kelulusan pelanggan melalui HQ.",
  "Reason for reassignment (required, 1–1000)": "Sebab penugasan semula (diperlukan, 1–1000)",
  "Reason (optional, kept with the change)": "Sebab (pilihan, disimpan bersama perubahan)",
  "A reason is required while the work is under way": "Sebab diperlukan semasa kerja sedang berjalan",
  "tech-external-a is on sick leave from today.": "tech-external-a bercuti sakit mulai hari ini.",
  "On save, {current} loses action access immediately. The job keeps its state; {name} continues in a new draft version and the original report authorship is kept.": "Apabila disimpan, {current} kehilangan akses tindakan serta-merta. Kerja kekal dalam keadaannya; {name} meneruskan dalam versi draf baharu dan kepengarangan laporan asal dikekalkan.",
  "the current technician": "juruteknik semasa",
  "The current technician accepted the assignment ✓": "Juruteknik semasa telah menerima penugasan ✓",
  "Waiting for the current technician to accept (受領).": "Menunggu juruteknik semasa menerima (受領).",
  "The technician could do {slot} instead — a different time needs the client’s approval via HQ.": "Juruteknik boleh melakukannya pada {slot} sebaliknya — masa lain memerlukan kelulusan pelanggan melalui HQ.",
  "No technician of your company can take this time (busy, unavailable or not qualified). Free a technician in Team & capacity, or ask HQ to agree another time with the client.": "Tiada juruteknik syarikat anda boleh mengambil masa ini (sibuk, tidak tersedia atau tidak layak). Kosongkan jadual juruteknik dalam Pasukan & kapasiti, atau minta HQ bersetuju dengan pelanggan tentang masa lain.",
  "No overlapping confirmed schedule for {name} in this window.": "Tiada jadual disahkan yang bertindih untuk {name} dalam tetingkap ini.",
  "{name}: {reason} — saving is refused.": "{name}: {reason} — penyimpanan ditolak.",
  "Save new slot": "Simpan slot baharu",
  "Reassigning a job already in progress requires a reason and immediately revokes the previous technician’s access.": "Menugaskan semula kerja yang sedang berjalan memerlukan sebab dan serta-merta membatalkan akses juruteknik sebelumnya.",
  "Technician assigned — waiting for acceptance": "Juruteknik ditugaskan — menunggu penerimaan",
  "Assignment changed": "Penugasan diubah",
  "Assigned {name} for {slot}. The technician must accept (受領); HQ and the technician are notified.": "{name} ditugaskan untuk {slot}. Juruteknik mesti menerima (受領); HQ dan juruteknik dimaklumkan.",
  "Changed to {name} for {slot}. The technician must accept (受領); HQ and the technician are notified.": "Ditukar kepada {name} untuk {slot}. Juruteknik mesti menerima (受領); HQ dan juruteknik dimaklumkan.",
  "Confirmed assignment": "Penugasan disahkan",
