  "Conflicts with {n} confirmed assignments: {list}. Saving keeps the assignments — reassign them in Schedule & assignments.": "Bertindih dengan {n} penugasan yang disahkan: {list}. Menyimpan mengekalkan penugasan itu — tugaskan semula dalam Jadual & tugasan.",
  "Unavailable days set the technician’s available hours to 0 for those dates, so utilization and candidate lists (members.eligible) skip them. For a public holiday of the whole team choose Public holiday and All technicians.": "Hari tidak tersedia menetapkan jam tersedia juruteknik kepada 0 untuk tarikh tersebut, jadi penggunaan dan senarai calon (members.eligible) melangkauinya. Untuk cuti umum seluruh pasukan, pilih Cuti umum dan Semua juruteknik.",
