  "CONFLICT — the job is not in a state that allows this (on hold, submitted or cancelled); the page shows the latest state.": "CONFLICT — kerja tidak berada dalam keadaan yang membenarkan ini (ditangguhkan, dihantar atau dibatalkan); halaman ini menunjukkan keadaan terkini.",
