  "You said you can’t make this time (“{reason}”). Your coordinator reassigns the job or asks the client for another time.": "Anda menyatakan tidak dapat hadir pada masa ini (“{reason}”). Penyelaras anda menugaskan semula kerja atau meminta masa lain daripada pelanggan.",
  "You said you can’t make this time. Your coordinator reassigns the job or asks the client for another time.": "Anda menyatakan tidak dapat hadir pada masa ini. Penyelaras anda menugaskan semula kerja atau meminta masa lain daripada pelanggan.",
  "Start job (check in)": "Mulakan kerja (daftar masuk)",
