  "On site: Start job opens Check in (location + unit QR); checking in starts the work (IR111).": "Di tapak: Mulakan kerja membuka Daftar masuk (lokasi + QR unit); daftar masuk memulakan kerja (IR111).",
  "On hold by HQ — saving and submitting are blocked (CONFLICT, IR93). Your saved draft is kept; continue when HQ resumes the job.": "Ditangguhkan oleh HQ — menyimpan dan menghantar disekat (CONFLICT, IR93). Draf yang disimpan dikekalkan; teruskan apabila HQ menyambung semula kerja.",
