  "Returned for rework. Resume to continue as a new draft version; the returned version stays as it was.": "Dikembalikan untuk kerja semula. Sambung untuk meneruskan sebagai versi draf baharu; versi yang dikembalikan kekal seperti asal.",
  "The work window ended — unsaved input was discarded and the job can no longer be edited (FORBIDDEN). Ask your coordinator.": "Tetingkap kerja telah tamat — input yang belum disimpan dibuang dan kerja tidak lagi boleh diedit (FORBIDDEN). Tanya penyelaras anda.",
