  "Automatic resolution needs a remeasurement {recovery} — or a reason below with alert.resolve.": "Penyelesaian automatik memerlukan pengukuran semula {recovery} — atau sebab di bawah dengan alert.resolve.",
  "No remeasurement resolves this alert — it has no policy. Resolve it with a reason below with alert.resolve (IR66).": "Tiada pengukuran semula yang menyelesaikan amaran ini — ia tiada dasar. Selesaikannya dengan sebab di bawah dengan alert.resolve (IR66).",
  "Resolved {time} — {reason}.": "Diselesaikan {time} — {reason}.",
  "Completing the job alone never resolves an alert. If the condition returns, a new alert is created with previousAlertId = {id}.": "Menyelesaikan kerja sahaja tidak pernah menyelesaikan amaran. Jika keadaan berulang, amaran baharu dicipta dengan previousAlertId = {id}.",
  "Recurrence after resolution creates a new alert with previousAlertId linking back to this one.": "Ulangan selepas penyelesaian mencipta amaran baharu dengan previousAlertId yang memaut kembali kepada amaran ini.",
  "Not resolved (FORBIDDEN) — you don’t have alert.resolve. The alert resolves automatically once a remeasurement stays {recovery}, or ask a permitted user.": "Tidak diselesaikan (FORBIDDEN) — anda tiada alert.resolve. Amaran diselesaikan secara automatik apabila pengukuran semula kekal {recovery}, atau minta pengguna yang dibenarkan.",
  "Not resolved (FORBIDDEN) — you don’t have alert.resolve. Ask a permitted user to resolve it.": "Tidak diselesaikan (FORBIDDEN) — anda tiada alert.resolve. Minta pengguna yang dibenarkan menyelesaikannya.",
