  "KPI → list links pass the same customer / property but not the period for current-state KPIs (units, alerts, unpaid); Back restores this URL including the period (IR50, D13).": "Pautan KPI → senarai menghantar pelanggan / premis yang sama tetapi bukan tempoh untuk KPI keadaan semasa (unit, amaran, belum dibayar); Kembali memulihkan URL ini termasuk tempoh (IR50, D13).",

