  "Response = request → offer accepted (contractor) or first assignment (internal). Arrival = technician check-in inside the scheduled slot. First-time fix = report accepted without rework and no repeat job on the unit within 30 days. Status compares each customer with its plan’s targets; metrics without data show “—”.": "Respons = permintaan → tawaran diterima (kontraktor) atau penugasan pertama (dalaman). Ketibaan = daftar masuk juruteknik dalam slot yang dijadualkan. Pembaikan kali pertama = laporan diterima tanpa kerja semula dan tiada kerja berulang pada unit dalam 30 hari. Status membandingkan setiap pelanggan dengan sasaran pelannya; metrik tanpa data menunjukkan “—”.",
