  "Keeps the unit ID; version {from} → {to}. Alert policies stay attached to the unit.": "Mengekalkan ID unit; versi {from} → {to}. Polisi amaran kekal dilampirkan pada unit.",
  "Delete unit": "Padam unit",
  "Removes the unit from lists, totals and candidates. The ID and history are kept (archived); active automations are disabled with reason unit_archived (IR39).": "Mengeluarkan unit daripada senarai, jumlah dan calon. ID dan sejarah disimpan (diarkibkan); automasi aktif dilumpuhkan dengan sebab unit_archived (IR39).",
  "CONFLICT · this unit is still in use": "CONFLICT · unit ini masih digunakan",
  "End or move these first. Ended history alone does not block deletion.": "Tamatkan atau pindahkan ini dahulu. Sejarah yang telah tamat sahaja tidak menyekat pemadaman.",
  "The blockers (contracts, jobs, device binding) are not visible with your permissions — the Core API checks them on delete.": "Penyekat (kontrak, kerja, pengikatan peranti) tidak kelihatan dengan kebenaran anda — Core API menyemaknya semasa memadam.",
  "Registered by mistake?": "Didaftarkan secara tersilap?",
  "A unit that never had contracts, jobs or IoT can be removed completely (units.delete); otherwise this is CONFLICT and the unit has to be deleted as above.": "Unit yang tidak pernah mempunyai kontrak, kerja atau IoT boleh dikeluarkan sepenuhnya (units.delete); jika tidak, ini ialah CONFLICT dan unit perlu dipadam seperti di atas.",
