  "Client users have no permission editor — the owner can also invite members from the customer app (Users). HQ, contractor and technician accounts are managed in Access & roles. The last active owner cannot be demoted, disabled or removed.": "Pengguna pelanggan tiada penyunting kebenaran — pemilik juga boleh menjemput ahli dari aplikasi pelanggan (Pengguna). Akaun HQ, kontraktor dan juruteknik diurus dalam Akses & peranan. Pemilik aktif terakhir tidak boleh diturunkan, dilumpuhkan atau dibuang.",
