  "The warranty end is set on the unit (unit edit › Warranty end) or by the CSV import. Coverage = an active maintenance contract, otherwise the warranty; fewer than 90 days left counts as ending (IR111).": "Tamat waranti ditetapkan pada unit (suntingan unit › Tamat waranti) atau melalui import CSV. Liputan = kontrak penyelenggaraan aktif, jika tidak waranti; kurang daripada 90 hari berbaki dikira sebagai akan tamat (IR111).",
  "Warranty on jobs": "Waranti pada kerja",
