  "No create, edit, or delete here. Secrets and contacts in before/after are masked. This browser demo does not guarantee tamper-proof storage.": "Tiada cipta, sunting atau padam di sini. Rahsia dan hubungan dalam sebelum/selepas bertopeng. Demo pelayar ini tidak menjamin storan kalis usik.",
